-- Hosted maintenance heartbeat; no participant or location data.
CREATE TABLE hosting_maintenance_runs(day date PRIMARY KEY,status text NOT NULL CHECK(status IN ('running','completed','failed')),started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,counts jsonb NOT NULL DEFAULT '{}');
ALTER TABLE hosting_maintenance_runs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON hosting_maintenance_runs FROM PUBLIC;
-- Supabase applies explicit default grants to API roles. ROVA uses its authenticated
-- backend, not direct Data API access to its tables, views or safety RPCs.
-- Touch only ROVA-owned names and the public PostGIS reference table if present.
DO $$ DECLARE who text; object record; BEGIN
 FOR who IN SELECT 'PUBLIC' UNION ALL SELECT rolname FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role') LOOP
  FOR object IN SELECT c.oid::regclass AS name FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v') AND c.relname=ANY(ARRAY['speed_limit_rules','audit_logs','road_segments','speed_rules','audit_events','official_speed_rule_imports','speed_rule_approvals','users','devices','push_tokens','data_sources','enforcement_zones','incident_reports','incident_confirmations','moderation_actions','driver_compliance_events','map_data_import_batches','map_road_candidates','reported_road_advisories','reported_road_advisory_segments','incident_sessions','incident_abuse_buckets','driver_preferences','driver_saved_places','driver_deletion_jobs','admin_members','admin_sessions','admin_revisions','admin_reviews','admin_action_logs','coverage_daily','notification_installations','notification_regions','policy_announcements','notification_queue','notification_reservations','sponsored_listings','sponsored_daily_metrics','provider_usage','provider_usage_state','pilot_telemetry_sessions','pilot_telemetry_batches','pilot_corridors','pilot_corridor_reviews','pilot_incident_checks','speed_rules','audit_events','published_road_segments','published_speed_limit_rules','published_enforcement_zones','published_incident_reports','community_incident_summary','current_policy_announcements','current_pilot_corridors','schema_migrations','hosting_maintenance_runs','spatial_ref_sys']) LOOP EXECUTE format('REVOKE ALL ON TABLE %s FROM %s',object.name,CASE WHEN who='PUBLIC' THEN 'PUBLIC' ELSE quote_ident(who) END);END LOOP;
  FOR object IN SELECT p.oid::regprocedure AS name FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=ANY(ARRAY['require_independent_speed_rule_approvals','rova_valid_wgs','guard_source_identity','enforce_record_provenance','audit_record_change','reject_audit_mutation','guard_speed_rule_revision','guard_road_review','guard_speed_review','audit_speed_review','rova_speed_limit_candidates','guard_compliance_event','rova_compliance_candidates','rova_reported_road_candidates','admin_content','guard_admin_publication','guard_policy_publication','pilot_counts_valid','pilot_members_current','guard_pilot_review','pilot_review_immutable','guard_pilot_activation']) LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %s',object.name,CASE WHEN who='PUBLIC' THEN 'PUBLIC' ELSE quote_ident(who) END);END LOOP;
 END LOOP;
END $$;
